import {
  execFile,
} from 'node:child_process';

import {
  mkdir,
  rm,
  writeFile,
} from 'node:fs/promises';

import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';

import {
  promisify,
} from 'node:util';

/* =========================================================
   CONFIG
========================================================= */

const execFileAsync =
  promisify(
    execFile,
  );

const ANGULAR_IMAGE =
  process.env.ANGULAR_IMAGE ??
  'elab-judge-angular:latest';

const RESULT_MARKER =
  '__ELAB_ANGULAR_RESULT__';


/* =========================================================
   TRUSTED ANGULAR TEST RUNNER

   Generated by the host Judge and written into the
   temporary learner workspace before Docker starts.
========================================================= */

const ANGULAR_TEST_RUNNER_SOURCE =
  "import {\n  readFile,\n  symlink,\n} from 'node:fs/promises';\n\nimport {\n  pathToFileURL,\n} from 'node:url';\n\nimport {\n  JSDOM,\n} from 'jsdom';\n\nimport * as esbuild from 'esbuild';\n\n/* =========================================================\n   CONFIG\n========================================================= */\n\nconst RESULT_MARKER =\n  '__ELAB_ANGULAR_RESULT__';\n\nconst TEST_FILE =\n  '/workspace/.elab-tests.json';\n\nconst APP_FILE =\n  '/workspace/app.component.ts';\n\nconst COMPILED_APP =\n  '/tmp/elab-angular-app.mjs';\n\n/* =========================================================\n   RESULT OUTPUT\n========================================================= */\n\nfunction emitResult(\n  result,\n) {\n  console.log(\n    `${RESULT_MARKER}${JSON.stringify(\n      result,\n    )}`,\n  );\n}\n\n/* =========================================================\n   PAGE TEXT\n========================================================= */\n\nfunction getPageText() {\n  return (\n    document.body\n      .textContent ??\n    ''\n  )\n    .replace(\n      /\\s+/g,\n      ' ',\n    )\n    .trim();\n}\n\n/* =========================================================\n   WAIT / CHANGE DETECTION\n========================================================= */\n\nasync function settle(\n  appRef,\n) {\n  await Promise.resolve();\n\n  await new Promise(\n    (\n      resolve,\n    ) => {\n      setTimeout(\n        resolve,\n        0,\n      );\n    },\n  );\n\n  if (\n    typeof appRef\n      ?.tick ===\n    'function'\n  ) {\n    appRef.tick();\n  }\n\n  await Promise.resolve();\n}\n\n/* =========================================================\n   TEXT TEST\n========================================================= */\n\nfunction runTextTest(\n  test,\n  index,\n) {\n  const actual =\n    getPageText();\n\n  const expected =\n    String(\n      test.text ??\n      '',\n    );\n\n  const passed =\n    actual.includes(\n      expected,\n    );\n\n  return {\n    testNumber:\n      index + 1,\n\n    type:\n      'text',\n\n    passed,\n\n    expected,\n\n    actual,\n\n    message:\n      passed\n        ? 'Expected text was rendered.'\n        : 'Expected text was not found.',\n  };\n}\n\n/* =========================================================\n   CLICK TEST\n========================================================= */\n\nasync function runClickTest(\n  test,\n  index,\n  appRef,\n) {\n  const selector =\n    String(\n      test.selector ??\n      '',\n    );\n\n  const element =\n    document.querySelector(\n      selector,\n    );\n\n  if (\n    !element\n  ) {\n    return {\n      testNumber:\n        index + 1,\n\n      type:\n        'click',\n\n      passed:\n        false,\n\n      selector,\n\n      message:\n        'Target element was not found.',\n    };\n  }\n\n  element.dispatchEvent(\n    new MouseEvent(\n      'click',\n      {\n        bubbles:\n          true,\n\n        cancelable:\n          true,\n      },\n    ),\n  );\n\n  await settle(\n    appRef,\n  );\n\n  const actual =\n    getPageText();\n\n  const expected =\n    String(\n      test.expectedText ??\n      '',\n    );\n\n  const absentText =\n    typeof test.absentText ===\n      'string'\n      ? test.absentText\n      : '';\n\n  const passed =\n    (\n      !expected ||\n      actual.includes(\n        expected,\n      )\n    ) &&\n    (\n      !absentText ||\n      !actual.includes(\n        absentText,\n      )\n    );\n\n  return {\n    testNumber:\n      index + 1,\n\n    type:\n      'click',\n\n    passed,\n\n    selector,\n\n    expected,\n\n    absentText,\n\n    actual,\n\n    message:\n      passed\n        ? 'Click produced the expected UI.'\n        : 'Expected UI was not produced after the click.',\n  };\n}\n\n/* =========================================================\n   INPUT TEST\n========================================================= */\n\nasync function runInputTest(\n  test,\n  index,\n  appRef,\n) {\n  const selector =\n    String(\n      test.selector ??\n      'input',\n    );\n\n  const element =\n    document.querySelector(\n      selector,\n    );\n\n  if (\n    !element\n  ) {\n    return {\n      testNumber:\n        index + 1,\n\n      type:\n        'input',\n\n      passed:\n        false,\n\n      selector,\n\n      message:\n        'Input element was not found.',\n    };\n  }\n\n  const value =\n    String(\n      test.value ??\n      '',\n    );\n\n  const prototype =\n    Object.getPrototypeOf(\n      element,\n    );\n\n  const descriptor =\n    Object.getOwnPropertyDescriptor(\n      prototype,\n      'value',\n    );\n\n  if (\n    descriptor\n      ?.set\n  ) {\n    descriptor.set.call(\n      element,\n      value,\n    );\n  } else {\n    element.value =\n      value;\n  }\n\n  element.dispatchEvent(\n    new Event(\n      'input',\n      {\n        bubbles:\n          true,\n      },\n    ),\n  );\n\n  element.dispatchEvent(\n    new Event(\n      'change',\n      {\n        bubbles:\n          true,\n      },\n    ),\n  );\n\n  await settle(\n    appRef,\n  );\n\n  const actual =\n    getPageText();\n\n  const expected =\n    String(\n      test.expectedText ??\n      '',\n    );\n\n  const absentText =\n    typeof test.absentText ===\n      'string'\n      ? test.absentText\n      : '';\n\n  const expectedFound =\n    !expected ||\n    actual.includes(\n      expected,\n    );\n\n  const absentRemoved =\n    !absentText ||\n    !actual.includes(\n      absentText,\n    );\n\n  const passed =\n    expectedFound &&\n    absentRemoved;\n\n  return {\n    testNumber:\n      index + 1,\n\n    type:\n      'input',\n\n    passed,\n\n    selector,\n\n    value,\n\n    expected,\n\n    absentText,\n\n    actual,\n\n    message:\n      passed\n        ? 'Input produced the expected UI.'\n        : 'Input did not produce the expected UI.',\n  };\n}\n\n/* =========================================================\n   EXECUTE TEST\n========================================================= */\n\nasync function executeTest(\n  test,\n  index,\n  appRef,\n) {\n  if (\n    test.type ===\n      'text'\n  ) {\n    return runTextTest(\n      test,\n      index,\n    );\n  }\n\n  if (\n    test.type ===\n      'click'\n  ) {\n    return await runClickTest(\n      test,\n      index,\n      appRef,\n    );\n  }\n\n  if (\n    test.type ===\n      'input'\n  ) {\n    return await runInputTest(\n      test,\n      index,\n      appRef,\n    );\n  }\n\n  return {\n    testNumber:\n      index + 1,\n\n    type:\n      String(\n        test.type ??\n        'unknown',\n      ),\n\n    passed:\n      false,\n\n    message:\n      'Unsupported Angular test type.',\n  };\n}\n\n/* =========================================================\n   MAIN\n========================================================= */\n\nasync function main() {\n  let appRef =\n    null;\n\n  try {\n    const config =\n      JSON.parse(\n        await readFile(\n          TEST_FILE,\n          'utf8',\n        ),\n      );\n\n    const tests =\n      Array.isArray(\n        config.tests,\n      )\n        ? config.tests\n        : [];\n\n    if (\n      tests.length ===\n        0\n    ) {\n      const result = {\n        passed:\n          false,\n\n        passedTests:\n          0,\n\n        totalTests:\n          0,\n\n        results: [],\n\n        message:\n          'No Angular tests were provided.',\n      };\n\n      emitResult(\n        result,\n      );\n\n      process.exitCode =\n        30;\n\n      return;\n    }\n\n    /*\n     * ESM resolution from /tmp needs access to packages\n     * installed under /runtime/node_modules.\n     */\n    try {\n      await symlink(\n        '/runtime/node_modules',\n        '/tmp/node_modules',\n        'dir',\n      );\n    } catch {\n      // Already exists.\n    }\n\n    /* =====================================================\n       COMPILE TYPESCRIPT COMPONENT\n    ===================================================== */\n\n    await esbuild.build({\n      entryPoints: [\n        APP_FILE,\n      ],\n\n      outfile:\n        COMPILED_APP,\n\n      bundle:\n        false,\n\n      format:\n        'esm',\n\n      platform:\n        'neutral',\n\n      target:\n        'es2022',\n\n      sourcemap:\n        false,\n\n      logLevel:\n        'silent',\n\n      tsconfigRaw: {\n        compilerOptions: {\n          experimentalDecorators:\n            true,\n\n          useDefineForClassFields:\n            false,\n\n          target:\n            'ES2022',\n        },\n      },\n    });\n\n    /* =====================================================\n       DOM\n    ===================================================== */\n\n    const dom =\n      new JSDOM(\n        '<!doctype html><html><body><app-root></app-root></body></html>',\n        {\n          url:\n            'http://localhost/',\n        },\n      );\n\n    globalThis.window =\n      dom.window;\n\n    globalThis.document =\n      dom.window.document;\n\n    /*\n     * Node.js 22 exposes globalThis.navigator through a\n     * getter-only property. Direct assignment throws.\n     */\n    Object.defineProperty(\n      globalThis,\n      'navigator',\n      {\n        value:\n          dom.window.navigator,\n\n        configurable:\n          true,\n\n        writable:\n          true,\n      },\n    );\n\n    globalThis.Node =\n      dom.window.Node;\n\n    globalThis.Element =\n      dom.window.Element;\n\n    globalThis.HTMLElement =\n      dom.window.HTMLElement;\n\n    globalThis.Event =\n      dom.window.Event;\n\n    globalThis.MouseEvent =\n      dom.window.MouseEvent;\n\n    globalThis.CustomEvent =\n      dom.window.CustomEvent;\n\n    globalThis.getComputedStyle =\n      dom.window.getComputedStyle.bind(\n        dom.window,\n      );\n\n    globalThis.requestAnimationFrame =\n      (\n        callback,\n      ) =>\n        setTimeout(\n          () =>\n            callback(\n              Date.now(),\n            ),\n          0,\n        );\n\n    globalThis.cancelAnimationFrame =\n      (\n        id,\n      ) =>\n        clearTimeout(\n          id,\n        );\n\n    /* =====================================================\n       ANGULAR JIT\n    ===================================================== */\n\n    await import(\n      'zone.js'\n    );\n\n    await import(\n      '@angular/compiler'\n    );\n\n    const {\n      bootstrapApplication,\n    } =\n      await import(\n        '@angular/platform-browser'\n      );\n\n    const learnerModule =\n      await import(\n        `${pathToFileURL(\n          COMPILED_APP,\n        ).href}?v=${Date.now()}`\n      );\n\n    const AppComponent =\n      learnerModule.AppComponent ??\n      learnerModule.default;\n\n    if (\n      typeof AppComponent !==\n        'function'\n    ) {\n      throw new Error(\n        'app.component.ts must export AppComponent.',\n      );\n    }\n\n    appRef =\n      await bootstrapApplication(\n        AppComponent,\n      );\n\n    await settle(\n      appRef,\n    );\n\n    /* =====================================================\n       RUN TESTS\n    ===================================================== */\n\n    const results = [];\n\n    for (\n      let index = 0;\n      index <\n        tests.length;\n      index += 1\n    ) {\n      results.push(\n        await executeTest(\n          tests[\n            index\n          ],\n          index,\n          appRef,\n        ),\n      );\n    }\n\n    const passedTests =\n      results.filter(\n        (\n          result,\n        ) =>\n          result.passed ===\n            true,\n      ).length;\n\n    const totalTests =\n      results.length;\n\n    const passed =\n      totalTests >\n        0 &&\n      passedTests ===\n        totalTests;\n\n    emitResult({\n      passed,\n\n      passedTests,\n\n      totalTests,\n\n      results,\n    });\n\n    if (\n      !passed\n    ) {\n      process.exitCode =\n        10;\n    }\n  } catch (\n    error\n  ) {\n    const result = {\n      passed:\n        false,\n\n      passedTests:\n        0,\n\n      totalTests:\n        0,\n\n      results: [],\n\n      message:\n        error instanceof\n          Error\n          ? error.message\n          : 'Angular build or render failed.',\n    };\n\n    emitResult(\n      result,\n    );\n\n    console.error(\n      error,\n    );\n\n    process.exitCode =\n      20;\n  } finally {\n    try {\n      appRef\n        ?.destroy();\n    } catch {\n      // Ignore cleanup errors.\n    }\n  }\n}\n\nawait main();\n";

/* =========================================================
   DEFAULT PUBLIC TESTS

   Used by Run when NestJS does not send hidden tests.
========================================================= */

function getDefaultTests(
  problemSlug,
) {
  if (
    problemSlug ===
    'angular-counter'
  ) {
    return [
      {
        type:
          'text',

        text:
          '0',
      },
      {
        type:
          'click',

        selector:
          'button',

        expectedText:
          '1',
      },
      {
        type:
          'click',

        selector:
          'button',

        expectedText:
          '2',
      },
    ];
  }

  if (
    problemSlug ===
    'angular-search-products'
  ) {
    return [
      {
        type:
          'text',

        text:
          'Laptop',
      },
      {
        type:
          'text',

        text:
          'Phone',
      },
      {
        type:
          'input',

        selector:
          'input',

        value:
          'phone',

        expectedText:
          'Phone',

        absentText:
          'Laptop',
      },
      {
        type:
          'input',

        selector:
          'input',

        value:
          'HEAD',

        expectedText:
          'Headphones',

        absentText:
          'Phone',
      },
    ];
  }

  if (
    problemSlug ===
    'angular-todo'
  ) {
    return [
      {
        type:
          'text',

        text:
          'Todo',
      },
      {
        type:
          'input',

        selector:
          'input',

        value:
          'Buy milk',
      },
      {
        type:
          'click',

        selector:
          'button',

        expectedText:
          'Buy milk',
      },
    ];
  }

  if (
    problemSlug ===
    'angular-user-directory'
  ) {
    return [
      {
        type:
          'text',

        text:
          'Alice Johnson',
      },
      {
        type:
          'text',

        text:
          'bob@example.com',
      },
      {
        type:
          'input',

        selector:
          'input',

        value:
          'DIANA',

        expectedText:
          'Diana Prince',

        absentText:
          'Alice Johnson',
      },
    ];
  }

  return [];
}

/* =========================================================
   SAFE FILE PATH
========================================================= */

function normalizeFilePath(
  filePath,
) {
  const normalized =
    String(
      filePath ??
      '',
    )
      .replace(
        /\\/g,
        '/',
      )
      .trim();

  if (
    !normalized ||
    normalized.startsWith(
      '/',
    ) ||
    normalized ===
      '..' ||
    normalized.includes(
      '../',
    )
  ) {
    throw new Error(
      `Invalid Angular file path: ${filePath}`,
    );
  }

  return normalized;
}

/* =========================================================
   WRITE LEARNER FILES
========================================================= */

async function writeLearnerFiles(
  workDirectory,
  files,
) {
  for (
    const file
    of files
  ) {
    const relativePath =
      normalizeFilePath(
        file.path,
      );

    const destination =
      path.join(
        workDirectory,
        relativePath,
      );

    const relativeCheck =
      path.relative(
        workDirectory,
        destination,
      );

    if (
      relativeCheck.startsWith(
        '..',
      ) ||
      path.isAbsolute(
        relativeCheck,
      )
    ) {
      throw new Error(
        `Invalid Angular file path: ${file.path}`,
      );
    }

    await mkdir(
      path.dirname(
        destination,
      ),
      {
        recursive:
          true,
      },
    );

    await writeFile(
      destination,
      String(
        file.content ??
        '',
      ),
      'utf8',
    );
  }
}

/* =========================================================
   PARSE RESULT
========================================================= */

function parseAngularResult(
  stdout,
) {
  const lines =
    String(
      stdout ??
      '',
    )
      .split(
        /\r?\n/,
      );

  for (
    let index =
      lines.length - 1;
    index >=
      0;
    index -=
      1
  ) {
    const line =
      lines[
        index
      ];

    if (
      !line.startsWith(
        RESULT_MARKER,
      )
    ) {
      continue;
    }

    const payload =
      line.slice(
        RESULT_MARKER.length,
      );

    try {
      return JSON.parse(
        payload,
      );
    } catch {
      return null;
    }
  }

  return null;
}

/* =========================================================
   CLEAN OUTPUT
========================================================= */

function cleanOutput(
  stdout,
) {
  return String(
    stdout ??
    '',
  )
    .split(
      /\r?\n/,
    )
    .filter(
      (
        line,
      ) =>
        !line.startsWith(
          RESULT_MARKER,
        ),
    )
    .join(
      '\n',
    )
    .trim();
}

/* =========================================================
   RUN ANGULAR FRAMEWORK
========================================================= */

export async function runAngularFramework({
  problemSlug,
  files,
  tests,
}) {
  if (
    !Array.isArray(
      files,
    ) ||
    files.length ===
      0
  ) {
    return {
      runtime:
        'angular',

      status:
        'INVALID_REQUEST',

      message:
        'At least one Angular file is required.',

      testResults: [],
    };
  }

  const resolvedTests =
    Array.isArray(
      tests,
    ) &&
    tests.length >
      0
      ? tests
      : getDefaultTests(
          problemSlug,
        );

  if (
    resolvedTests.length ===
    0
  ) {
    return {
      runtime:
        'angular',

      status:
        'INVALID_REQUEST',

      message:
        `No Angular tests configured for ${problemSlug}.`,

      testResults: [],
    };
  }

  const executionId =
    crypto.randomUUID();

  const workDirectory =
    path.join(
      os.tmpdir(),
      `elab-angular-${executionId}`,
    );

  await mkdir(
    workDirectory,
    {
      recursive:
        true,
    },
  );

  try {
    await writeLearnerFiles(
      workDirectory,
      files,
    );

    await writeFile(
      path.join(
        workDirectory,
        '.elab-tests.json',
      ),
      JSON.stringify(
        {
          problemSlug,
          tests:
            resolvedTests,
        },
      ),
      'utf8',
    );

    /* =====================================================
       WRITE TRUSTED ANGULAR RUNNER

       Same architecture used by the React Judge:
       host creates the runner, Docker only executes it.
    ===================================================== */

    await writeFile(
      path.join(
        workDirectory,
        '__elab_angular_runner.mjs',
      ),
      ANGULAR_TEST_RUNNER_SOURCE,
      'utf8',
    );

    const dockerArgs = [
      'run',
      '--rm',

      '--network',
      'none',

      '--memory',
      '512m',

      '--memory-swap',
      '512m',

      '--cpus',
      '0.5',

      '--pids-limit',
      '64',

      '--cap-drop',
      'ALL',

      '--security-opt',
      'no-new-privileges',

      '--read-only',

      '--tmpfs',
      '/tmp:rw,exec,nosuid,nodev,size=256m',

      '--mount',
      `type=bind,source=${workDirectory},target=/workspace,readonly`,

      /*
       * Mount the same temporary workspace under /runtime as well.
       * The trusted Angular ESM runner executes from /runtime/workspace
       * so Node can resolve packages from /runtime/node_modules.
       */
      '--mount',
      `type=bind,source=${workDirectory},target=/runtime/workspace,readonly`,

      ANGULAR_IMAGE,

      'node',
      '/runtime/workspace/__elab_angular_runner.mjs',
    ];

    try {
      const {
        stdout,
        stderr,
      } =
        await execFileAsync(
          'docker',
          dockerArgs,
          {
            windowsHide:
              true,

            timeout:
              20_000,

            maxBuffer:
              5 *
              1024 *
              1024,
          },
        );

      const result =
        parseAngularResult(
          stdout,
        );

      const output =
        cleanOutput(
          stdout,
        );

      if (
        !result
      ) {
        return {
          runtime:
            'angular',

          status:
            'RUNTIME_ERROR',

          output,

          stderr:
            String(
              stderr ??
              '',
            ).trim(),

          message:
            'Angular Judge did not return a valid result.',

          testResults: [],
        };
      }

      return {
        runtime:
          'angular',

        status:
          result.passed
            ? 'SUCCESS'
            : 'TEST_FAILED',

        output,

        stderr:
          String(
            stderr ??
            '',
          ).trim(),

        passedTests:
          result.passedTests ??
          0,

        totalTests:
          result.totalTests ??
          resolvedTests.length,

        testResults:
          Array.isArray(
            result.results,
          )
            ? result.results
            : [],
      };
    } catch (
      error
    ) {
      if (
        error?.killed ||
        error?.signal ===
          'SIGTERM'
      ) {
        return {
          runtime:
            'angular',

          status:
            'TIME_LIMIT_EXCEEDED',

          output:
            cleanOutput(
              error?.stdout ??
              '',
            ),

          stderr:
            String(
              error?.stderr ??
              '',
            ).trim(),

          message:
            'Angular execution exceeded the time limit.',

          testResults: [],
        };
      }

      const exitCode =
        typeof error?.code ===
        'number'
          ? error.code
          : null;

      const stdout =
        String(
          error?.stdout ??
          '',
        );

      const stderr =
        String(
          error?.stderr ??
          '',
        ).trim();

      const result =
        parseAngularResult(
          stdout,
        );

      const output =
        cleanOutput(
          stdout,
        );

      if (
        exitCode ===
          10
      ) {
        return {
          runtime:
            'angular',

          status:
            'TEST_FAILED',

          output,

          stderr,

          passedTests:
            result
              ?.passedTests ??
            0,

          totalTests:
            result
              ?.totalTests ??
            resolvedTests.length,

          testResults:
            Array.isArray(
              result?.results,
            )
              ? result.results
              : [],
        };
      }

      if (
        exitCode ===
          20
      ) {
        return {
          runtime:
            'angular',

          status:
            'BUILD_ERROR',

          output,

          stderr,

          message:
            result
              ?.message ??
            'Angular component could not be compiled or rendered.',

          testResults: [],
        };
      }

      if (
        exitCode ===
          30
      ) {
        return {
          runtime:
            'angular',

          status:
            'INVALID_REQUEST',

          output,

          stderr,

          message:
            result
              ?.message ??
            `No Angular tests configured for ${problemSlug}.`,

          testResults: [],
        };
      }

      return {
        runtime:
          'angular',

        status:
          'RUNTIME_ERROR',

        output,

        stderr,

        message:
          result
            ?.message ??
          'Angular application execution failed.',

        testResults:
          Array.isArray(
            result?.results,
          )
            ? result.results
            : [],
      };
    }
  } finally {
    await rm(
      workDirectory,
      {
        recursive:
          true,

        force:
          true,
      },
    );
  }
}
